<template><div class="space-y-4"><el-input v-model="names" type="textarea" :rows="6" placeholder="输入名单，每行一个，也支持逗号分隔"/><el-input-number v-model="count" :min="1" :max="50" placeholder="分组数"/><el-button size="small" type="primary" @click="group">随机分组</el-button><div v-if="groups.length" class="grid gap-3 md:grid-cols-2"><div v-for="(g,i) in groups" :key="i" class="rounded-xl bg-gray-50 p-3 dark:bg-gray-700"><b>第{{ i+1 }}组</b>：{{ g.join('、') }}</div></div></div></template>
<script setup lang="ts">import { ref } from 'vue';const names=ref(''),count=ref(2),groups=ref<string[][]>([]);const group=()=>{const a=names.value.split(/[\n,，]+/).map(x=>x.trim()).filter(Boolean).sort(()=>Math.random()-.5);groups.value=Array.from({length:Math.min(count.value,a.length||1)},()=>[]);a.forEach((x,i)=>groups.value[i%groups.value.length].push(x))}</script>
